mkdir -p /Users/marksuyat/.claude/panes/state/runs/1789426425-20705-24633/work && cd /Users/marksuyat/.claude/panes/state/runs/1789426425-20705-24633/work && S="judge_0012_$$" && cat > probe.sql <<EOF
-- Independent reproduction of spec 0012 §5.5's worked example (judge probe, throwaway schema).
CREATE SCHEMA $S;
SET search_path TO $S;
CREATE TABLE seasons (id int PRIMARY KEY, name text);
CREATE TABLE season_rounds (id int PRIMARY KEY, season_id int, round_number int);
CREATE TABLE brackets (id serial PRIMARY KEY, round_id int, season_id int, user_id int, UNIQUE(round_id,user_id));
CREATE TABLE leaderboard_entries (id serial PRIMARY KEY, season_id int, user_id int, total_points int, exact_call_count int, bracket_completed_at timestamptz, UNIQUE(season_id,user_id));
CREATE TABLE queens (id int PRIMARY KEY, name text);
CREATE TABLE outcome_events (id serial PRIMARY KEY, season_id int, event_type text, queen_id int, supersedes_event_id int, episode_number int);
INSERT INTO seasons VALUES (14,'Season 14'),(15,'Season 15'),(16,'Season 16'),(17,'Season 17'),(18,'Season 18'),(19,'Season 19');
INSERT INTO season_rounds VALUES (141,14,1),(151,15,1),(161,16,1),(171,17,1),(172,17,2),(181,18,1),(182,18,2),(191,19,1);
-- player 1 brackets: 14 r1 (incomplete -> no row), 15 r1, 16 r1, 17 r1+r2, 18 r1; never 19
INSERT INTO brackets(round_id,season_id,user_id) VALUES (141,14,1),(151,15,1),(161,16,1),(171,17,1),(172,17,1),(181,18,1),(191,19,2);
-- season 14: two others scored, player 1 no row
INSERT INTO leaderboard_entries(season_id,user_id,total_points,exact_call_count,bracket_completed_at) VALUES
 (14,2,50,1,'2027-01-01'),(14,3,40,1,'2027-01-01'),
 -- season 15: p3 ahead; p1 and p2 full-key tie
 (15,3,200,5,'2027-01-01'),(15,2,100,2,'2027-01-01'),(15,1,100,2,'2027-01-01'),
 -- season 16: sole player
 (16,1,60,1,'2027-01-01'),
 -- season 17: four players, p1 second with 240
 (17,4,300,6,'2027-01-01'),(17,1,240,5,'2027-01-01'),(17,2,200,4,'2027-01-01'),(17,3,100,1,'2027-01-01');
INSERT INTO queens VALUES (74,'Queen 14A'),(76,'Queen 16A'),(87,'Wrong Crown'),(88,'Corrected Crown');
INSERT INTO outcome_events(season_id,event_type,queen_id,supersedes_event_id,episode_number) VALUES
 (14,'SEASON_END',74,NULL,10),(16,'SEASON_END',76,NULL,10),(17,'SEASON_END',87,NULL,12);
INSERT INTO outcome_events(season_id,event_type,queen_id,supersedes_event_id,episode_number)
 SELECT 17,'SEASON_END',88,id,12 FROM outcome_events WHERE season_id=17 AND queen_id=87;

\echo '--- Q1 (spec 5.1, verbatim) ---'
WITH my_seasons AS (SELECT DISTINCT season_id FROM brackets WHERE user_id = 1),
ranked AS (
  SELECT le.season_id, le.user_id, le.total_points,
         ROW_NUMBER() OVER (PARTITION BY le.season_id
           ORDER BY le.total_points DESC, le.exact_call_count DESC, le.bracket_completed_at ASC, le.user_id ASC) AS finish
  FROM leaderboard_entries le WHERE le.season_id IN (SELECT season_id FROM my_seasons)),
scored AS (SELECT season_id, COUNT(*) AS player_count FROM leaderboard_entries
  WHERE season_id IN (SELECT season_id FROM my_seasons) GROUP BY season_id)
SELECT s.id AS season_id, s.name AS season_name, COALESCE(sc.player_count,0) AS player_count,
       (sc.season_id IS NOT NULL) AS is_scored, r.finish, r.total_points
FROM my_seasons ms JOIN seasons s ON s.id = ms.season_id
LEFT JOIN scored sc ON sc.season_id = ms.season_id
LEFT JOIN ranked r ON r.season_id = ms.season_id AND r.user_id = 1
ORDER BY s.id DESC;

\echo '--- Rule 1 check: RANK() vs ROW_NUMBER() on season 15 ---'
SELECT user_id, RANK() OVER w AS rnk, ROW_NUMBER() OVER w AS rn FROM leaderboard_entries WHERE season_id=15
WINDOW w AS (ORDER BY total_points DESC, exact_call_count DESC, bracket_completed_at ASC, user_id ASC);

\echo '--- Rule 2 trap: filter inside the window CTE (season 17, player 1 is really 2nd of 4) ---'
SELECT season_id, ROW_NUMBER() OVER (PARTITION BY season_id ORDER BY total_points DESC) AS finish,
       COUNT(*) OVER (PARTITION BY season_id) AS player_count
FROM leaderboard_entries WHERE season_id=17 AND user_id=1;

\echo '--- Q2 ---'
SELECT b.season_id, sr.round_number FROM brackets b JOIN season_rounds sr ON sr.id=b.round_id
WHERE b.user_id=1 ORDER BY b.season_id DESC, sr.round_number ASC;

\echo '--- Q3/Q4 effective SEASON_END winners (supersession resolved per season) ---'
SELECT e.season_id, e.queen_id, q.name FROM outcome_events e JOIN queens q ON q.id=e.queen_id
WHERE e.event_type='SEASON_END'
  AND e.id NOT IN (SELECT supersedes_event_id FROM outcome_events WHERE supersedes_event_id IS NOT NULL)
ORDER BY e.season_id DESC, e.id;

DROP SCHEMA $S CASCADE;
EOF
docker exec -i snatch-bracket-db-1 psql -U snatch -d snatch_bracket -v ON_ERROR_STOP=1 < probe.sql 2>&1
